package dev.wildcraft.test;
import dev.wildcraft.client.animation.rig.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.entity.state.AvatarRenderState;
import net.minecraft.world.entity.HumanoidArm;
import org.joml.Matrix4f;
import org.joml.Vector3f;
import java.util.*;
/** Observes actual submitted native sprite against sampled draw-hand; diagnostic item calls are excluded from GPU counts. */
public final class AirBowAudit {
    private static final java.util.Map<net.minecraft.world.entity.player.PlayerModelType,net.minecraft.client.model.player.PlayerModel> MODELS=new java.util.EnumMap<>(net.minecraft.world.entity.player.PlayerModelType.class);
    public static volatile boolean enabled;public static final java.util.concurrent.atomic.AtomicInteger shots=new java.util.concurrent.atomic.AtomicInteger();private static boolean registered;public static int frames,draws,holds;public static float maxStringGap;public static long eligibleSince;public static boolean fullSeen;public static int firstHold,maxMissingTick;public static boolean expectActive;public static Set<Integer> stages=new TreeSet<>();
    public static void begin(){enabled=true;frames=draws=holds=0;firstHold=-1;maxMissingTick=-1;eligibleSince=0;fullSeen=false;expectActive=false;maxStringGap=0;stages.clear();shots.set(0);if(!registered){registered=true;net.fabricmc.fabric.api.event.lifecycle.v1.ServerEntityEvents.ENTITY_LOAD.register((entity,world)->{if(enabled&&entity instanceof net.minecraft.world.entity.projectile.arrow.AbstractArrow arrow&&arrow.getOwner() instanceof net.minecraft.world.entity.player.Player)shots.incrementAndGet();});}}
    private static Vector3f point(net.minecraft.client.renderer.item.ItemStackRenderState item,HumanoidArm arm,Vector3f raw){var layer=(dev.wildcraft.mixin.client.FusionLayerAccessor)((dev.wildcraft.mixin.client.FusionStateAccessor)item).wildcraft$layers()[0];var pose=new com.mojang.blaze3d.vertex.PoseStack();layer.wildcraft$transform().apply(arm==HumanoidArm.LEFT,pose.last());pose.mulPose(layer.wildcraft$local());return pose.last().pose().transformPosition(raw);}
    public static void coverage(net.minecraft.world.entity.player.Player p,AvatarRenderState s){
        if(!enabled||!expectActive||p!=Minecraft.getInstance().player)return;
        if(!p.isUsingItem()||p.onGround()){eligibleSince=0;fullSeen=false;return;}
        long now=System.nanoTime();if(eligibleSince==0)eligibleSince=now;int ticks=p.getTicksUsingItem();var f=s.getData(CombatRigLayer.FRAME);
        if(f==null||!f.clip().startsWith("bow_air_")){maxMissingTick=Math.max(maxMissingTick,ticks);if(fullSeen||(now-eligibleSince)/1e9>.20)throw new AssertionError("Actual qualified airborne source lost after real entry envelope, nativeTicks="+ticks+" elapsed="+(now-eligibleSince)/1e9);return;}
        fullSeen|=f.weight()>.999;if(ticks>=20!=f.clip().contains("hold"))throw new AssertionError("Source hold/draw does not match actual native 20-tick use: "+ticks);
    }
    public static void observe(AvatarRenderState s){var f=s.getData(CombatRigLayer.FRAME);if(!enabled||f==null||!f.clip().startsWith("bow_air_"))return;var c=Minecraft.getInstance();int ticks=c.player.getTicksUsingItem();frames++;if(f.clip().contains("draw"))draws++;else {holds++;if(firstHold<0)firstHold=ticks;}int stage=ticks>=18?2:ticks>=13?1:0;stages.add(stage);var arm=c.player.getUsedItemHand()==net.minecraft.world.InteractionHand.MAIN_HAND?c.player.getMainArm():c.player.getMainArm().getOpposite();String bowSide=arm==HumanoidArm.LEFT?"left":"right",drawingSide=arm==HumanoidArm.LEFT?"right":"left";var item=arm==HumanoidArm.LEFT?s.leftHandItemState:s.rightHandItemState;var material=item.pickParticleMaterial(net.minecraft.util.RandomSource.create(0));String actualSprite=material.sprite().contents().name().toString();if(!actualSprite.equals("minecraft:item/bow_pulling_"+stage))throw new AssertionError("Native bow pull sprite differs from actual use-duration: "+ticks+" "+actualSprite);if(f.weight()<.999999)return;
        Matrix4f held;DodgeFeedbackAudit.checkingNativeItem=true;try{held=CombatRig.heldPose(f,item,arm,false);}finally{DodgeFeedbackAudit.checkingNativeItem=false;}
        var names=Arrays.asList(f.data().bones());var ref=new Matrix4f(CombatRigLayer.BASIS).mul(f.global()[names.indexOf(bowSide+"_sword_reference")]);var raw=new Vector3f(.21875F,.46875F,.5F);var actual=held.transformPosition(point(item,arm,raw));if(actual.distance(ref.getTranslation(new Vector3f()))>.00002)throw new AssertionError("True native wood grip detached");
        var right=new Matrix4f(CombatRigLayer.BASIS).mul(f.global()[names.indexOf(drawingSide+"_palm_grip")]).getTranslation(new Vector3f());float x=(10.5F+stage)/16F,y=1-(9.5F+stage)/16F;var string=held.transformPosition(point(item,arm,new Vector3f(x,y,.5F)));float gap=right.distance(string);maxStringGap=Math.max(maxStringGap,gap);if(gap>.00003)throw new AssertionError("Actual native arrow nock is detached from drawing hand: "+gap);
        var unadapted=CombatRig.sample(s.skin.model()==net.minecraft.world.entity.player.PlayerModelType.SLIM?"slim":"standard",f.clip(),f.time());for(int i=0;i<f.global().length;i++){String bone=names.get(i);if(bone.equals("head")||bone.startsWith(drawingSide+"_")&&(bone.contains("arm")||bone.contains("elbow")||bone.contains("wrist")||bone.contains("palm")||bone.contains("reference")||bone.contains("mount")))continue;var baseline=s.getData(FocusLegRig.PULSE)!=null&&FocusLegAudit.before!=null&&FocusLegAudit.leg(bone)?FocusLegAudit.before[i]:f.global()[i];float[] a=unadapted[i].get(new float[16]),b=baseline.get(new float[16]);for(int k=0;k<16;k++)if(Math.abs(a[k]-b[k])>.00002)throw new AssertionError("Drawing arm adapter changed source body/bow hand "+bone);}
        for(String joint:new String[]{drawingSide+"_elbow_deform",drawingSide+"_palm_grip"}){String origin=joint.equals(drawingSide+"_elbow_deform")?drawingSide+"_upper_arm":drawingSide+"_elbow_deform";int a=names.indexOf(origin),b=names.indexOf(joint);float source=unadapted[a].getTranslation(new Vector3f()).distance(unadapted[b].getTranslation(new Vector3f())),actualLength=f.global()[a].getTranslation(new Vector3f()).distance(f.global()[b].getTranslation(new Vector3f()));if(Math.abs(source-actualLength)>.00003)throw new AssertionError("Drawing adapter stretched source arm "+joint);}
        var model=MODELS.computeIfAbsent(s.skin.model(),type->{boolean slim=type==net.minecraft.world.entity.player.PlayerModelType.SLIM;return new net.minecraft.client.model.player.PlayerModel(net.minecraft.client.model.geom.builders.LayerDefinition.create(net.minecraft.client.model.player.PlayerModel.createMesh(net.minecraft.client.model.geom.builders.CubeDeformation.NONE,slim),64,64).bakeRoot(),slim);});model.setupAnim(s);var nativePose=new com.mojang.blaze3d.vertex.PoseStack();model.head.translateAndRotate(nativePose);var aim=new Matrix4f(CombatRigLayer.BASIS).mul(nativePose.last().pose()).mul(CombatRigLayer.BASIS).getUnnormalizedRotation(new org.joml.Quaternionf()).normalize();if(Math.abs(aim.dot(f.global()[names.indexOf("head")].getUnnormalizedRotation(new org.joml.Quaternionf()).normalize()))<.99999)throw new AssertionError("Ground bow source changed native head aim");
        if(f.clip().contains("draw")&&Math.abs(f.time()-CombatRig.pullSample(f.data().clips().get(f.clip()),ticks/20F))>.000001)throw new AssertionError("Draw advanced independently of actual native use ticks");if(holds==1||draws==1)System.out.println("C6Q STRING ticks="+ticks+" stage="+stage+" hand="+right+" nativeString="+string+" gap="+gap);
    }
}
